var e=[{title:`Mit csinál egy-egy régió`,text:`A háti gerinc a hátad középső szakasza, amely lehetővé teszi a forgást és a nyújtást. A vállkomplexum magában foglalja a gömbcsuklót és a bordakosáron csúszó lapockát. A fej feletti nyúlás több régió együttműködésén múlik, ezért többet tesztel a vállízület hajlékonyságánál.`},{title:`Fedezd fel a kényelmes mozgást`,text:`Egy nyitott könyv forgatási gyakorlat gyengéden elforgatja a felsőtestedet, miközben a csípőd viszonylag mozdulatlan marad. A kontrollált karkörzések a vállmozgást próbálják el, a macska-tehén pedig könnyű tempóban hajlítja és nyújtja a gerincet. Mozogj lassan, lélegezz normálisan, és ne erőltesd a végállást.`},{title:`Mozgékonyság az emeléseidben`,text:`A fej feletti nyomás gördülékenyebbnek érződhet, ha a bordáid, a lapockáid és a karjaid együtt mozognak. Evezésnél hagyd, hogy a lapockáid természetesen mozogjanak; nem kell végig hátrafeszítve tartanod őket. A választott gyakorlatban a gördülékeny kontrollra törekedj. Nincs egyetlen merev testtartás, amelyet mindenkinek másolnia kell.`},{title:`Mozgékonyság és erő együtt`,text:`A könnyű nyomások, a falcsúsztatások, az evezések és a kontrollált hordozások együtt építenek használható tartományt és koordinációt. A nyújtás önmagában javíthatja a passzív hajlékonyságot anélkül, hogy teljes kontrollt adna terhelés alatt. Ha egy gyakorlat instabilnak vagy kényelmetlennek érződik, változtass a fogáson, a szögön vagy a mozgástartományon.`},{title:`A TrainUp használata`,text:`Ha a fej feletti munka zavarja a válladat, add hozzá a vállat korlátként a Profilban, megjegyzéssel. A terv csak olyan gyakorlatokat választ, amelyek illenek a korlátaidhoz. Új, tartós vagy rosszabbodó vállfájdalom esetén fordulj orvoshoz vagy gyógytornászhoz ahelyett, hogy általános mozgékonysági gyakorlatokra támaszkodnál.`}];var l=[{label:`ACE 2026: mozgékonyság és hajlékonyság`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: gyakorlati nyújtási útmutató`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE gyakorlatkönyvtár`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var o={sections:e,sources:l};export{o as default,e as sections,l as sources};